from sheet import evaluate, CycleError

def eq(cells, name, want):
    got = evaluate(cells)[name]
    assert abs(got - want) < 1e-9, (cells, name, got, want)

eq({"A": "3.5"}, "A", 3.5)
eq({"A": "7", "B": "=A/2"}, "B", 3.5)
eq({"A": "=3/2"}, "A", 1.5)
eq({"A": "=1-2-3"}, "A", -4.0)
eq({"A": "=8/4/2"}, "A", 1.0)
eq({"A": "=2+3*4-6/3"}, "A", 12.0)
eq({"A": "=(1+2)*3"}, "A", 9.0)
eq({"A": "= 1 + 2 * 3 ", "B": "=\t(A\n)+1"}, "B", 5.0)

eq({"A": "=-3"}, "A", -3.0)
eq({"A": "2", "B": "=-(A+1)"}, "B", -3.0)
eq({"A": "=2*-3"}, "A", -6.0)
eq({"A": "=--4"}, "A", 4.0)
eq({"A": "=1--2"}, "A", 3.0)
eq({"A": "=-3+10"}, "A", 7.0)

out = evaluate({"A": "=B+C", "B": "=D*2", "C": "1.5", "D": "=E", "E": "4"})
assert out == {"A": 10.5, "B": 8.0, "C": 1.5, "D": 4.0, "E": 4.0}, out
assert all(isinstance(v, float) for v in out.values())

eq({"TOTAL": "5", "X12": "=TOTAL*TOTAL", "OUT": "=X12+TOTAL"}, "OUT", 30.0)

for c in ({"A": "=1/0"}, {"A": "0", "B": "= 3 / A"}):
    try:
        evaluate(c)
    except ZeroDivisionError:
        pass
    else:
        raise AssertionError(f"expected ZeroDivisionError for {c}")

for bad in ({"A": "=A"}, {"A": "=B", "B": "=A"},
            {"A": "=B", "B": "=C", "C": "=A"},
            {"OK": "1", "A": "=OK+B", "B": "=A"}):
    try:
        evaluate(bad)
    except CycleError as e:
        assert "cycle" in str(e).lower(), str(e)
    else:
        raise AssertionError(f"expected CycleError for {bad}")

N = 20000
cells = {"C0": "1"}
for i in range(1, N):
    cells[f"C{i}"] = f"=C{i-1}+1"
assert evaluate(cells)[f"C{N-1}"] == float(N)

assert evaluate({"A": "=" + "+".join(["1"] * 5000)})["A"] == 5000.0
assert evaluate({}) == {}

for bad_cells in ({"A": "=1+"}, {"A": "=(1+2"}, {"A": "=1$2"}, {"A": "=1 2"},
                  {"A": "hello"}, {"A": "="}, {"A": "=A+"}):
    try:
        evaluate(bad_cells)
    except (ValueError, TypeError):
        pass
    else:
        raise AssertionError(f"expected error for {bad_cells}")

try:
    evaluate({"A": "=NOPE"})
except KeyError:
    pass
else:
    raise AssertionError("expected KeyError for unknown ref")

print("all checks passed")
